def bachgold_problem(n):
    if n <= 3:
        return [n]

    primes = []
    while n % 2 == 0:
        primes.append(2)
        n //= 2

    i = 3
    while i * i <= n:
        while n % i == 0:
            primes.append(i)
            n //= i
        i += 2

    if n > 2:
        primes.append(n)

    return primes

