def bachgold_problem(n):
    # If n is even, we can always express it as a sum of 2's
    if n % 2 == 0:
        return n // 2, [2] * (n // 2)

    # If n is odd and greater than 4, we can express it as (n-3) + 3
    if n > 4:
        return n - 3 + 1, [2] + [3] * (n - 3)

    # If n is 4, we can express it as 2 + 2
    if n == 4:
        return 2, [2, 2]

